  (d.setAside = d.setAside || []).push({ at: new Date().toISOString(), by: roleName(), why, figure, sigName: bp.sigName || "",
    kept: before.filter((e) => !after.has(line(e))).map((e) => ({ at: e.at, what: e.what, who: e.who })),
    paper: JSON.parse(JSON.stringify(bp)) });
